#include <bits/stdc++.h>
using namespace std;

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> transformed;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                transformed.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : transformed) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : transformed) { x -= minx; y -= miny; }
            sort(transformed.begin(), transformed.end());
            if (seen.insert(transformed).second) {
                int maxx = 0, maxy = 0;
                for (auto [x, y] : transformed) { maxx = max(maxx, x); maxy = max(maxy, y); }
                res.push_back({transformed, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for (int j = 0; j < ksz[i]; j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) allOrients[i] = getOrientations(raw[i]);

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (ksz[a] != ksz[b]) return ksz[a] > ksz[b];
        return allOrients[a].size() < allOrients[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    int sqrtArea = max(1, (int)ceil(sqrt((double)totalCells)));

    vector<int> candidates;
    for (int w = max(1, sqrtArea/2); w <= min(totalCells, sqrtArea * 4); w++) candidates.push_back(w);

    auto t0 = chrono::steady_clock::now();

    for (int W : candidates) {
        if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-t0).count() > 8500) break;

        int Hmax = totalCells / W + n * 10 + 20;
        if ((long long)W * Hmax > 10000000LL) Hmax = 10000000 / W;
        if (Hmax < 1) continue;

        vector<vector<bool>> grid(W, vector<bool>(Hmax, false));
        vector<int> colH(W, 0);

        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;
        int curMaxH = 0;

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by=-1, boi=-1;

            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& ori = allOrients[i][oi];
                if (ori.w > W) continue;

                for (int x = 0; x <= W - ori.w; x++) {
                    int startY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        startY = max(startY, colH[x+cx] - cy);
                    }
                    if (startY < 0) startY = 0;

                    bool placed = false;
                    for (int y = startY; y + ori.h <= Hmax; y++) {
                        bool ok = true;
                        for (auto [cx, cy] : ori.cells) {
                            if (grid[x+cx][y+cy]) { ok = false; break; }
                        }
                        if (ok) {
                            int newH = max(curMaxH, y + ori.h);
                            int score = newH * 100000 + y * 1000 + x;
                            if (score < bestScore) {
                                bestScore = score; bx = x; by = y; boi = oi;
                            }
                            placed = true;
                            break;
                        }
                    }
                    if (placed && by == 0) break;
                }
            }

            if (boi < 0) { valid = false; break; }

            auto& ori = allOrients[i][boi];
            px[i] = bx; py[i] = by; pr[i] = ori.r; pf[i] = ori.f;
            for (auto [cx, cy] : ori.cells) {
                grid[bx+cx][by+cy] = true;
                colH[bx+cx] = max(colH[bx+cx], by+cy+1);
                curMaxH = max(curMaxH, by+cy+1);
            }
        }

        if (!valid) continue;

        int H = curMaxH;
        int area = W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area; bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    if (bestArea == INT_MAX) {
        // Fallback: single row
        bestW = totalCells; bestH = 1;
        int cx = 0;
        for (int i = 0; i < n; i++) {
            bestX[i] = cx; bestY[i] = 0; bestR[i] = 0; bestF[i] = 0;
            // Place horizontally: use first orientation that fits in height 1
            // Actually just spread monominos - use raw cells normalized
            // Simple: place each cell set shifted
            cx += ksz[i]; // This won't work for non-line shapes
        }
        // Ultra fallback: huge grid, place each piece far apart
        bestW = totalCells * 10 + 10; bestH = 12;
        int xoff = 0;
        for (int i = 0; i < n; i++) {
            bestX[i] = xoff; bestY[i] = 0; bestR[i] = 0; bestF[i] = 0;
            auto& ori = allOrients[i][0];
            xoff += ori.w + 1;
        }
        bestW = xoff; bestH = 12;
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
}
